+        document.getElementById('latest-hkdf-salt').textContent =
+          envelope.aead.hkdfSaltB64;
+
+        const kemParts = [];
+        if (envelope.encapsulation.ephemeralPublicKeyB64) {
+          kemParts.push('ECDH EPK (65B)');
+        }
+        if (envelope.encapsulation.pqCiphertextB64) {
+          kemParts.push('ML-KEM-768 CT (' + envelope.encapsulation.pqCiphertextBytes + 'B)');
+        }
+        if (envelope.encapsulation.rsaCiphertextB64) {
+          kemParts.push('RSA-OAEP CT (256B)');
+        }
+        document.getElementById('latest-kem-summary').textContent =
+          kemParts.join(' + ') + ' | Secret FP: ' + envelope.encapsulation.sharedSecretFingerprint.slice(0, 17);
+
+        document.getElementById('latest-ciphertext').textContent = envelope.aead.ciphertextB64;
+        document.getElementById('latest-aad').textContent = envelope.aead.aadString;
+
+        // Compact display copy for JSON inspector
+        const displayEnvelope = JSON.parse(JSON.stringify(envelope));
+        if (displayEnvelope.encapsulation.pqCiphertextB64 && displayEnvelope.encapsulation.pqCiphertextB64.length > 96) {
+          displayEnvelope.encapsulation.pqCiphertextPreview =
+            displayEnvelope.encapsulation.pqCiphertextB64.slice(0, 64) + '... (' + envelope.encapsulation.pqCiphertextBytes + ' bytes)';
+        }
+        document.getElementById('encrypted-json-output').textContent = JSON.stringify(envelope, null, 2);
+      }
+
+      function showToast(message, type) {
+        const toast = document.getElementById('encryption-status-toast');
+        toast.textContent = message;
+        toast.className = 'status-toast visible ' + (type || 'success');
+      }
+
+      function saveNotesToStorage() {
+        try {
+          // Only store encrypted envelopes (never plaintext)
+          localStorage.setItem(STORAGE_KEY, JSON.stringify(state.notes));
+        } catch (err) {
+          // Ignore storage quota errors in restricted environments
+        }
+      }
+
+      function renderEncryptedNotesList() {
