+            </div>
+            <div class="cipher-preview">
+              <div><strong>Ciphertext:</strong> <span class="ct-text"></span></div>
+              <div><strong>GCM Tag (128b):</strong> ${envelope.aead.authTagHex} | <strong>IV (96b):</strong> ${envelope.aead.ivHex}</div>
