+  Vec *c = (Vec *)calloc(w * h, sizeof(Vec));
+
+  for (int y = 0; y < h; y++) {
+    unsigned short Xi[3] = {0, 0, (unsigned short)(y * y * y)};
+    for (unsigned short x = 0; x < w; x++) {
+      for (int sy = 0, i = (h - y - 1) * w + x; sy < 2; sy++) {
+        for (int sx = 0; sx < 2; sx++, r = Vec()) {
+          for (int s = 0; s < samps; s++) {
+            double r1 = 2 * erand48(Xi),
+                   dx = r1 < 1 ? sqrt(r1) - 1 : 1 - sqrt(2 - r1);
+            double r2 = 2 * erand48(Xi),
+                   dy = r2 < 1 ? sqrt(r2) - 1 : 1 - sqrt(2 - r2);
+            Vec d = cx * (((sx + .5 + dx) / 2 + x) / w - .5) +
+                    cy * (((sy + .5 + dy) / 2 + y) / h - .5) + cam.d;
+            r = r + radiance(Ray(cam.o + d * 140, d.norm()), 0, Xi) *
+                        (1. / samps);
+          }
+          c[i] = c[i] + Vec(clamp(r.x), clamp(r.y), clamp(r.z)) * .25;
+        }
+      }
+    }
+  }
+
+  for (int i = 0; i < w * h; i++) {
+    out_rgba[i * 4 + 0] = (uint8_t)toInt(c[i].x);
+    out_rgba[i * 4 + 1] = (uint8_t)toInt(c[i].y);
+    out_rgba[i * 4 + 2] = (uint8_t)toInt(c[i].z);
+    out_rgba[i * 4 + 3] = 255;
+  }
+
+  free(c);
+}
