+
+EMSCRIPTEN_KEEPALIVE
+void set_sphere_color(int index, double r, double g, double b) {
+  if (index >= 0 && index < numSpheres) {
+    spheres[index].c = Vec(r, g, b);
+  }
+}
+
+EMSCRIPTEN_KEEPALIVE
+void randomize_sphere_colors(unsigned int seed) {
+  unsigned short Xi[3] = {
+    (unsigned short)(seed & 0xFFFF),
+    (unsigned short)((seed >> 16) & 0xFFFF),
+    (unsigned short)((seed ^ 0x5DEECE66DULL) & 0xFFFF)
+  };
+  // Randomize visible walls and spheres (indices 0, 1, 2, 4, 5, 6, 7)
+  int targets[] = {0, 1, 2, 4, 5, 6, 7};
+  for (int idx = 0; idx < 7; idx++) {
+    int i = targets[idx];
+    if (i == 6 || i == 7) {
+      // Tinted mirror and glass spheres (keep bright so reflections/refractions pop)
+      double r = 0.35 + 0.649 * erand48(Xi);
+      double g = 0.35 + 0.649 * erand48(Xi);
+      double b = 0.35 + 0.649 * erand48(Xi);
+      spheres[i].c = Vec(r, g, b);
+    } else {
+      // Diffuse walls
+      double r = 0.15 + 0.75 * erand48(Xi);
+      double g = 0.15 + 0.75 * erand48(Xi);
+      double b = 0.15 + 0.75 * erand48(Xi);
+      spheres[i].c = Vec(r, g, b);
+    }
+  }
+}
+
+EMSCRIPTEN_KEEPALIVE
+double get_sphere_color_channel(int index, int channel) {
+  if (index < 0 || index >= numSpheres) return 0.0;
+  if (channel == 0) return spheres[index].c.x;
+  if (channel == 1) return spheres[index].c.y;
+  if (channel == 2) return spheres[index].c.z;
+  return 0.0;
+}
+
+EMSCRIPTEN_KEEPALIVE
+uint8_t* init_render(int w, int h) {
+  if (w != current_w || h != current_h || !rgba_buffer || !accum_buffer) {
+    if (rgba_buffer) free(rgba_buffer);
+    if (accum_buffer) delete[] accum_buffer;
+    current_w = w;
+    current_h = h;
+    rgba_buffer = (uint8_t*)malloc(w * h * 4);
+    accum_buffer = new Vec[w * h];
+  }
+  for (int i = 0; i < w * h; i++) {
+    accum_buffer[i] = Vec();
+    rgba_buffer[i * 4 + 0] = 0;
+    rgba_buffer[i * 4 + 1] = 0;
+    rgba_buffer[i * 4 + 2] = 0;
+    rgba_buffer[i * 4 + 3] = 255;
+  }
+  return rgba_buffer;
+}
+
+EMSCRIPTEN_KEEPALIVE
+uint8_t* render_rows(int w, int h, int start_y, int end_y, int samps, int pass) {
+  if (!rgba_buffer || w != current_w || h != current_h) {
+    init_render(w, h);
+  }
+  if (samps < 1) samps = 1;
+  if (start_y < 0) start_y = 0;
+  if (end_y > h) end_y = h;
+
+  Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm());
+  Vec cx = Vec(w * .5135 / h), cy = (cx % cam.d).norm() * .5135, r;
+
+  for (int y = start_y; y < end_y; y++) {
+    for (unsigned short x = 0; x < w; x++) {
+      unsigned short Xi[3] = {
+        (unsigned short)(x + pass * 97),
+        (unsigned short)(y + pass * 313),
+        (unsigned short)(y * y * y + pass * 7919)
+      };
+      int i = (h - y - 1) * w + x;
+      Vec pixel_sample = Vec();
+      for (int sy = 0; sy < 2; sy++) {
+        for (int sx = 0; sx < 2; sx++, r = Vec()) {
+          for (int s = 0; s < samps; s++) {
+            double r1 = 2 * erand48(Xi), dx = r1 < 1 ? sqrt(r1) - 1 : 1 - sqrt(2 - r1);
+            double r2 = 2 * erand48(Xi), dy = r2 < 1 ? sqrt(r2) - 1 : 1 - sqrt(2 - r2);
+            Vec d = cx * (((sx + .5 + dx) / 2 + x) / w - .5) +
+                    cy * (((sy + .5 + dy) / 2 + y) / h - .5) + cam.d;
+            r = r + radiance(Ray(cam.o + d * 140, d.norm()), 0, Xi) * (1. / samps);
+          }
+          pixel_sample = pixel_sample + Vec(clamp(r.x), clamp(r.y), clamp(r.z)) * .25;
+        }
+      }
+      if (pass <= 1) {
+        accum_buffer[i] = pixel_sample;
+      } else {
+        accum_buffer[i] = accum_buffer[i] * ((double)(pass - 1) / pass) + pixel_sample * (1.0 / pass);
+      }
+      rgba_buffer[i * 4 + 0] = (uint8_t)toInt(accum_buffer[i].x);
+      rgba_buffer[i * 4 + 1] = (uint8_t)toInt(accum_buffer[i].y);
+      rgba_buffer[i * 4 + 2] = (uint8_t)toInt(accum_buffer[i].z);
+      rgba_buffer[i * 4 + 3] = 255;
+    }
+  }
+  return rgba_buffer;
+}
+
+EMSCRIPTEN_KEEPALIVE
+uint8_t* render(int w, int h, int samps) {
+  init_render(w, h);
+  return render_rows(w, h, 0, h, samps, 1);
+}
+
+EMSCRIPTEN_KEEPALIVE
+uint8_t* get_rgba_buffer() {
+  return rgba_buffer;
+}
+
+} // extern "C"
