+    (function () {
+      const toggleBtn = document.getElementById('theme-toggle');
+      const themeIcon = toggleBtn.querySelector('.theme-icon');
+      const themeText = toggleBtn.querySelector('.theme-text');
+      const root = document.documentElement;
+      const body = document.body;
+      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
+
+      function getEffectiveTheme() {
+        const stored = localStorage.getItem('theme');
+        if (stored === 'dark' || stored === 'light') {
+          return stored;
+        }
+        return mediaQuery.matches ? 'dark' : 'light';
+      }
+
+      function applyTheme(theme) {
+        const isDark = theme === 'dark';
+
+        root.setAttribute('data-theme', theme);
+        body.setAttribute('data-theme', theme);
+
+        root.classList.toggle('dark-theme', isDark);
+        root.classList.toggle('light-theme', !isDark);
+        body.classList.toggle('dark-theme', isDark);
+        body.classList.toggle('light-theme', !isDark);
+        body.classList.toggle('dark-mode', isDark);
+        body.classList.toggle('light-mode', !isDark);
+
+        toggleBtn.setAttribute('aria-pressed', String(isDark));
+        toggleBtn.setAttribute('aria-label', isDark ? 'Switch to light mode' : 'Switch to dark mode');
+        themeIcon.textContent = isDark ? '☀️' : '🌙';
+        themeText.textContent = isDark ? 'Light Mode' : 'Dark Mode';
+      }
+
+      // Initialize theme on load
+      applyTheme(getEffectiveTheme());
+
+      // Manual toggle overriding system preference
+      toggleBtn.addEventListener('click', () => {
+        const currentTheme = root.getAttribute('data-theme') || getEffectiveTheme();
+        const nextTheme = currentTheme === 'dark' ? 'light' : 'dark';
+        localStorage.setItem('theme', nextTheme);
+        applyTheme(nextTheme);
+      });
+
+      // Listen for system theme changes only if user hasn't set a manual override
+      mediaQuery.addEventListener('change', (e) => {
+        if (!localStorage.getItem('theme')) {
+          applyTheme(e.matches ? 'dark' : 'light');
+        }
+      });
+    })();
+  </script>
