diff --git a/src/components/TopStoriesSlider.tsx b/src/components/TopStoriesSlider.tsx
new file mode 100644
index 0000000..c9c3fab
--- /dev/null
+++ b/src/components/TopStoriesSlider.tsx
@@ -0,0 +1,109 @@
+import React, { useState, useEffect } from 'react';
+import { ChevronLeftIcon, ChevronRightIcon } from '@heroicons/react/24/outline';
+
+export interface TopStoryItem {
+  id: string;
+  title: string;
+  date: string;
+}
+
+interface TopStoriesSliderProps {
+  stories: TopStoryItem[];
+}
+
+export default function TopStoriesSlider({ stories }: TopStoriesSliderProps) {
+  const [currentIndex, setCurrentIndex] = useState(0);
+  const [direction, setDirection] = useState<'next' | 'prev' | null>(null);
+  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);
+
+  useEffect(() => {
+    if (typeof window === 'undefined' || !window.matchMedia) return;
+    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
+    setPrefersReducedMotion(mediaQuery.matches);
+
+    const handleChange = (event: MediaQueryListEvent) => {
+      setPrefersReducedMotion(event.matches);
+    };
+
+    mediaQuery.addEventListener('change', handleChange);
+    return () => mediaQuery.removeEventListener('change', handleChange);
+  }, []);
+
+  if (!stories || stories.length === 0) {
+    return null;
+  }
+
+  const checkReducedMotion = () => {
+    if (typeof window !== 'undefined' && window.matchMedia) {
+      return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
+    }
+    return prefersReducedMotion;
+  };
+
+  const handlePrevious = () => {
+    const reduced = checkReducedMotion();
+    setPrefersReducedMotion(reduced);
+    setDirection('prev');
+    setCurrentIndex((prevIndex) => (prevIndex - 1 + stories.length) % stories.length);
+  };
+
+  const handleNext = () => {
+    const reduced = checkReducedMotion();
+    setPrefersReducedMotion(reduced);
+    setDirection('next');
+    setCurrentIndex((prevIndex) => (prevIndex + 1) % stories.length);
+  };
+
+  const currentStory = stories[currentIndex];
+  const animationClass =
+    direction === 'next'
+      ? 'slide-in-right motion-reduce:animate-none'
+      : direction === 'prev'
+        ? 'slide-in-left motion-reduce:animate-none'
+        : '';
+
+  return (
+    <div
+      className="flex items-center justify-between gap-4"
+      role="region"
+      aria-roledescription="carousel"
+      aria-label="Top Stories"
+    >
+      <button
+        type="button"
+        onClick={handlePrevious}
+        aria-label="Previous"
+        className="flex items-center gap-1 px-3 py-1.5 text-sm font-semibold text-gray-700 hover:text-amber-500 border border-gray-300 rounded hover:border-amber-400 transition-colors shrink-0 cursor-pointer"
+      >
+        <ChevronLeftIcon className="w-4 h-4" aria-hidden="true" />
+        <span>Previous</span>
+      </button>
+
+      <div className="flex-1 overflow-hidden" aria-live="polite">
+        <div
+          key={currentStory.id}
+          data-direction={direction ?? undefined}
+          className={`w-full text-center ${animationClass}`.trim()}
+          style={prefersReducedMotion ? { animation: 'none', transition: 'none' } : undefined}
+        >
+          <a href={`${import.meta.env.BASE_URL}articles/${currentStory.id}`}>
+            <h3 className="font-bold text-gray-900 hover:text-amber-400 cursor-pointer">
+              {currentStory.title}
+            </h3>
+          </a>
+          <span className="text-xs text-gray-500">{currentStory.date}</span>
+        </div>
+      </div>
+
+      <button
+        type="button"
+        onClick={handleNext}
+        aria-label="Next"
+        className="flex items-center gap-1 px-3 py-1.5 text-sm font-semibold text-gray-700 hover:text-amber-500 border border-gray-300 rounded hover:border-amber-400 transition-colors shrink-0 cursor-pointer"
+      >
+        <span>Next</span>
+        <ChevronRightIcon className="w-4 h-4" aria-hidden="true" />
+      </button>
+    </div>
+  );
+}
