+              <span
+                data-permission-status="loopback-network"
+                className={`text-xs font-mono px-2 py-0.5 rounded border ${getBadgeStyle(
+                  loopbackCli.permissionState
+                )}`}
+                title="Permission state for 'loopback-network'"
+              >
+                {loopbackCli.permissionState}
+              </span>
+            </div>
+
+            <p className="text-xs text-slate-300 leading-relaxed">
+              Connects to the local DevTools Times companion CLI daemon running on your machine (
+              <code>127.0.0.1</code>, <code>[::1]</code>, or <code>localhost</code>). Uses{' '}
+              <code>permission: &apos;loopback-network&apos;</code> and{' '}
+              <code>targetAddressSpace: &apos;loopback&apos;</code>.
+            </p>
+
+            {/* Prompt explanation when state === 'prompt' */}
+            {loopbackCli.permissionState === 'prompt' && (
+              <div className="bg-slate-900/90 border border-slate-700 rounded p-2.5 text-xs text-slate-300">
+                <strong className="text-sky-300">Why access is needed:</strong> Clicking connect
