+
+            {/* Remediation box when state === 'denied' */}
+            <div
+              data-remediation="loopback-network"
+              hidden={loopbackCli.permissionState !== 'denied'}
+              className="bg-red-950/90 border border-red-700 rounded p-3 text-xs text-red-200 space-y-1"
+            >
+              <p className="font-semibold text-red-100">
+                Loopback Network Permission Denied (<code>loopback-network</code>)
+              </p>
+              <p>
+                To re-enable access to your local companion CLI: click the tune/lock icon in your
+                browser&apos;s address bar → open <strong>Site settings</strong> → set{' '}
+                <strong>Loopback network</strong> to <strong>Allow</strong>, then retry below.
+              </p>
+            </div>
+
+            <div className="space-y-2 pt-1">
+              <label className="block text-xs text-slate-400">
+                Companion CLI Health Endpoint (<code>127.0.0.1</code> / <code>localhost</code>)
+                <input
+                  type="url"
+                  value={loopbackCli.url}
+                  onChange={(e) => setLoopbackCli((prev) => ({ ...prev, url: e.target.value }))}
+                  placeholder="http://127.0.0.1:45678/health"
+                  className="mt-1 w-full bg-slate-950 border border-slate-700 rounded px-2.5 py-1.5 text-xs font-mono text-white focus:outline-none focus:border-sky-400"
+                />
+              </label>
+
+              <label className="block text-xs text-slate-400">
+                Companion CLI WebSocket Event Bus (<code>ws://127.0.0.1</code>)
+                <input
+                  type="text"
+                  value={loopbackCli.wsUrl}
+                  onChange={(e) => setLoopbackCli((prev) => ({ ...prev, wsUrl: e.target.value }))}
+                  placeholder="ws://127.0.0.1:45678/events"
+                  className="mt-1 w-full bg-slate-950 border border-slate-700 rounded px-2.5 py-1.5 text-xs font-mono text-white focus:outline-none focus:border-sky-400"
+                />
+              </label>
+            </div>
+          </div>
+
+          <div className="space-y-2 pt-2">
+            <div className="flex flex-wrap gap-2">
+              <button
+                type="button"
+                onClick={() => connectToLoopbackCli(loopbackCli.url)}
+                disabled={loopbackCli.status === 'connecting'}
+                className="bg-sky-400 hover:bg-sky-300 disabled:opacity-50 text-slate-950 font-semibold text-xs px-3 py-1.5 rounded transition cursor-pointer"
+              >
+                {loopbackCli.status === 'connecting'
+                  ? 'Connecting to Loopback CLI…'
+                  : 'Connect Companion CLI (HTTP)'}
+              </button>
+              <button
+                type="button"
+                onClick={() => handleLoopbackWebSocketStream(loopbackCli.wsUrl)}
+                disabled={loopbackCli.wsStatus === 'connecting'}
+                className="bg-slate-700 hover:bg-slate-600 text-white font-semibold text-xs px-3 py-1.5 rounded transition cursor-pointer"
+              >
+                {loopbackCli.wsStatus === 'connecting'
+                  ? 'Attaching CLI Bus…'
+                  : 'Attach Event Stream (WS)'}
+              </button>
+            </div>
+
+            {loopbackCli.errorMessage && (
+              <div
+                role="alert"
+                className="bg-red-950/70 border border-red-800 rounded p-2 text-xs text-red-200"
+              >
+                {loopbackCli.errorMessage}
+              </div>
+            )}
+
+            {loopbackCli.responsePayload && (
+              <pre className="bg-slate-950 border border-slate-800 rounded p-2 text-[11px] font-mono text-sky-300 overflow-x-auto max-h-28">
+                {JSON.stringify(loopbackCli.responsePayload, null, 2)}
+              </pre>
+            )}
+          </div>
+        </div>
+      </div>
+    </div>
+  );
+
+  if (variant === 'header') {
+    return (
+      <>
+        <button
+          type="button"
+          onClick={() => setIsOpen((prev) => !prev)}
+          className="inline-flex items-center space-x-1.5 bg-slate-900 hover:bg-slate-800 text-amber-300 border border-slate-700 text-xs font-semibold py-1.5 px-2.5 rounded cursor-pointer"
+          aria-expanded={isOpen}
+        >
+          <span className="h-2 w-2 rounded-full bg-amber-400" />
+          <span>Dev Diagnostics (LAN / CLI)</span>
+        </button>
+        {isOpen && (
+          <div
+            className="fixed inset-0 bg-black/40 backdrop-blur-xs z-[99999] flex justify-center items-start p-4 pt-[10vh]"
+            onClick={() => setIsOpen(false)}
+          >
+            <div className="w-full max-w-4xl" onClick={(e) => e.stopPropagation()}>
+              {renderPanelContent()}
+            </div>
+          </div>
+        )}
+      </>
+    );
+  }
+
+  return <section className="my-4">{renderPanelContent()}</section>;
+}
