new file mode 100644
index 0000000..4ece579
--- /dev/null
+++ b/src/utils/passkeys.ts
@@ -0,0 +1,191 @@
+export interface PasskeyCredential {
+  id: string;
+  credentialId: string;
+  displayName: string;
+  deviceType: string;
+  createdAt: string;
+  lastUsedAt: string;
+  backedUp?: boolean;
+}
+
+export interface ReaderAccount {
+  userId: string; // base64url-encoded user handle
+  username: string;
+  displayName: string;
+  email: string;
+  subscriptionTier: string;
+}
+
+export interface SyncResult {
+  synced: boolean;
+  method: 'signalAllAcceptedCredentials' | 'signalUnknownCredential' | 'signalCurrentUserDetails';
+  message: string;
+  timestamp: string;
+}
+
+export const DEFAULT_READER_ACCOUNT: ReaderAccount = {
+  userId: 'dXNlci1kZXZ0b29scy10aW1lcy0wMDE',
+  username: 'alex.rivera@devtoolstimes.com',
+  displayName: 'Alex Rivera',
+  email: 'alex.rivera@devtoolstimes.com',
+  subscriptionTier: 'Digital All-Access Subscriber',
+};
+
+export const DEFAULT_PASSKEYS: PasskeyCredential[] = [
+  {
+    id: 'pk-1',
+    credentialId: 'vI0qOggiE3OT01ZRWBYz5l4MEgU0c7PmAA',
+    displayName: 'MacBook Pro (Chrome Profile)',
+    deviceType: 'Platform Authenticator (Touch ID)',
+    createdAt: '2026-06-15',
+    lastUsedAt: '2026-11-04',
+    backedUp: true,
+  },
+  {
+    id: 'pk-2',
+    credentialId: 'k9LmN2pQrS4tUvWxYz0123456789AbCdEf',
+    displayName: 'Pixel 9 Pro (Google Password Manager)',
+    deviceType: 'Synced Passkey',
+    createdAt: '2026-08-22',
+    lastUsedAt: '2026-10-29',
+    backedUp: true,
+  },
+  {
+    id: 'pk-3',
+    credentialId: 'x7Yz9AbCdEfGhIjKlMnOpQrStUvWxYz12',
+    displayName: 'Office YubiKey 5C NFC',
+    deviceType: 'Roaming Security Key',
+    createdAt: '2026-03-10',
+    lastUsedAt: '2026-07-12',
+    backedUp: false,
+  },
+];
+
+export function getRpId(): string {
+  if (typeof window !== 'undefined' && window.location?.hostname) {
+    return window.location.hostname;
+  }
+  return 'localhost';
+}
+
+export function toBase64Url(bytes: Uint8Array): string {
+  let binary = '';
+  for (let i = 0; i < bytes.byteLength; i++) {
+    binary += String.fromCharCode(bytes[i]);
+  }
+  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export function stringToBase64Url(input: string): string {
+  const bytes = new TextEncoder().encode(input);
+  return toBase64Url(bytes);
+}
+
+/**
+ * Signals the complete list of accepted credential IDs for the current user to the browser authenticator
+ * so any removed or stale passkeys are pruned from the authenticator UI.
+ */
+export async function syncAllAcceptedCredentials(
+  userId: string,
+  allAcceptedCredentialIds: string[],
+  rpId: string = getRpId()
+): Promise<SyncResult> {
+  const timestamp = new Date().toLocaleTimeString();
+
+  if (
+    typeof window !== 'undefined' &&
+    'PublicKeyCredential' in window &&
+    typeof PublicKeyCredential.signalAllAcceptedCredentials === 'function'
+  ) {
+    await PublicKeyCredential.signalAllAcceptedCredentials({
+      rpId,
+      userId,
+      allAcceptedCredentialIds,
+    });
+    return {
+      synced: true,
+      method: 'signalAllAcceptedCredentials',
+      message: `Synchronized ${allAcceptedCredentialIds.length} active passkey(s) with browser authenticator.`,
+      timestamp,
+    };
+  }
+
+  return {
+    synced: false,
+    method: 'signalAllAcceptedCredentials',
+    message: 'Updated passkey list on server (PublicKeyCredential.signalAllAcceptedCredentials not supported by this browser).',
+    timestamp,
+  };
+}
+
+/**
