+const http = require('node:http');
+const fs = require('node:fs');
+const path = require('node:path');
+const crypto = require('node:crypto');
+
+const PORT = Number(process.env.PORT) || 11222;
+const ROOT_DIR = __dirname;
+
+const MIME_TYPES = {
+  '.html': 'text/html; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.js': 'application/javascript; charset=utf-8',
+  '.json': 'application/json; charset=utf-8',
+  '.svg': 'image/svg+xml',
+  '.png': 'image/png',
+  '.jpg': 'image/jpeg',
+  '.ico': 'image/x-icon'
+};
+
+function setPrivacyAndSecurityHeaders(res) {
+  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
+  res.setHeader(
+    'Permissions-Policy',
+    'geolocation=(), camera=(), microphone=(), accelerometer=(), focus-without-user-activation=()'
+  );
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+  res.setHeader('X-Frame-Options', 'DENY');
+  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains; preload');
+  res.setHeader('Cross-Origin-Opener-Policy', 'same-origin-allow-popups');
+  res.setHeader('Cross-Origin-Resource-Policy', 'same-origin');
+  res.setHeader('Vary', 'Sec-Fetch-Dest, Sec-Fetch-Mode, Sec-Fetch-Site');
+  res.setHeader(
+    'Content-Security-Policy',
+    "base-uri 'none'; object-src 'none'; frame-ancestors 'none'; form-action 'self'; frame-src https://www.youtube-nocookie.com;"
+  );
+  // Secure session & CHIPS partitioned cookie defaults
+  res.setHeader('Set-Cookie', [
+    '__Host-session_id=ephemeral; Secure; HttpOnly; SameSite=Lax; Path=/',
+    'theme_pref=light; SameSite=None; Secure; Path=/; Partitioned; HttpOnly'
+  ]);
+}
+
+// Rate limiter for sensitive endpoints (e.g., profile/account views) to prevent bulk scraping
+const rateLimitMap = new Map();
+function isRateLimited(ip) {
+  const now = Date.now();
+  const windowMs = 60 * 1000;
+  const maxRequests = 30;
+  const record = rateLimitMap.get(ip) || { count: 0, resetAt: now + windowMs };
+  if (now > record.resetAt) {
+    record.count = 0;
+    record.resetAt = now + windowMs;
+  }
+  record.count += 1;
+  rateLimitMap.set(ip, record);
+  return record.count > maxRequests;
+}
+
+const server = http.createServer((req, res) => {
+  setPrivacyAndSecurityHeaders(res);
+
+  // Fetch Metadata resource isolation check
+  const site = req.headers['sec-fetch-site'];
+  const mode = req.headers['sec-fetch-mode'];
+  const dest = req.headers['sec-fetch-dest'];
+  if (
+    site &&
+    !['same-origin', 'same-site', 'none'].includes(site) &&
+    !(site === 'cross-site' && mode === 'navigate' && req.method === 'GET' && !['object', 'embed'].includes(dest))
+  ) {
+    res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
+    res.end('Forbidden by Fetch Metadata Isolation Policy');
+    return;
+  }
+
+  const clientIp = req.socket.remoteAddress || 'unknown';
+  if (isRateLimited(clientIp)) {
+    res.writeHead(429, { 'Content-Type': 'text/plain; charset=utf-8' });
+    res.end('Too Many Requests');
+    return;
+  }
+
+  const reqUrl = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);
+
+  // Clear-Site-Data on Logout
+  if (reqUrl.pathname === '/logout') {
+    res.setHeader('Clear-Site-Data', '"*"');
+    res.setHeader('Set-Cookie', [
+      '__Host-session_id=; Max-Age=0; Secure; HttpOnly; SameSite=Lax; Path=/',
+      'theme_pref=; Max-Age=0; SameSite=None; Secure; Path=/; Partitioned; HttpOnly'
+    ]);
+    res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
+    res.end(JSON.stringify({ ok: true, cleared: '*' }));
+    return;
+  }
+
+  const safePath = path.normalize(reqUrl.pathname === '/' ? '/index.html' : reqUrl.pathname).replace(/^(\.\.[/\\])+/, '');
+  const filePath = path.join(ROOT_DIR, safePath);
+
+  fs.readFile(filePath, (err, content) => {
+    if (err) {
+      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
+      res.end('Not Found');
+      return;
+    }
+    const ext = path.extname(filePath).toLowerCase();
+    res.writeHead(200, { 'Content-Type': MIME_TYPES[ext] || 'application/octet-stream' });
+    res.end(content);
+  });
+});
+
+if (require.main === module) {
+  server.listen(PORT, () => {
+    console.log(`Daily Grind privacy-hardened server listening on http://localhost:${PORT}`);
+  });
+}
+
+module.exports = { server, setPrivacyAndSecurityHeaders };

