+const http = require('node:http');
+const fs = require('node:fs');
+const path = require('node:path');
+
+const PORT = Number(process.env.PORT) || 11222;
+const ROOT_DIR = __dirname;
+
+const CSP_HEADER = [
+  "default-src 'self'",
+  "connect-src 'self'",
+  "img-src 'self' https://images.unsplash.com",
+  "style-src 'self' 'unsafe-inline'",
+  "script-src 'self' 'unsafe-inline'",
+  "form-action 'self'",
+  "base-uri 'self'",
+  "frame-ancestors 'self'",
+  "object-src 'none'"
+].join('; ');
+
+const MIME_TYPES = {
+  '.html': 'text/html; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.js': 'application/javascript; charset=utf-8',
+  '.json': 'application/json; charset=utf-8',
+  '.png': 'image/png',
+  '.jpg': 'image/jpeg',
+  '.jpeg': 'image/jpeg',
+  '.svg': 'image/svg+xml',
+  '.ico': 'image/x-icon'
+};
+
+const subscriptions = [];
+
+function parseBody(req) {
+  return new Promise((resolve, reject) => {
+    let raw = '';
+    req.on('data', (chunk) => {
+      raw += chunk;
+      if (raw.length > 1e6) {
+        req.destroy();
+        reject(new Error('Payload too large'));
+      }
+    });
+    req.on('end', () => {
+      const contentType = (req.headers['content-type'] || '').toLowerCase();
+      if (!raw) {
+        return resolve({});
+      }
+      if (contentType.includes('application/json')) {
+        try {
+          return resolve(JSON.parse(raw));
+        } catch {
+          return resolve({});
+        }
+      }
+      if (contentType.includes('application/x-www-form-urlencoded')) {
+        const params = new URLSearchParams(raw);
+        return resolve(Object.fromEntries(params.entries()));
+      }
+      try {
+        return resolve(JSON.parse(raw));
+      } catch {
+        const params = new URLSearchParams(raw);
+        return resolve(Object.fromEntries(params.entries()));
+      }
+    });
+    req.on('error', reject);
+  });
+}
+
+function setSecurityHeaders(res) {
+  res.setHeader('Content-Security-Policy', CSP_HEADER);
+}
+
+const server = http.createServer(async (req, res) => {
+  setSecurityHeaders(res);
+
+  const url = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);
+  const pathname = url.pathname;
+
+  if (
+    req.method === 'POST' &&
+    (pathname === '/newsletter' ||
+      pathname === '/api/newsletter' ||
+      pathname === '/subscribe' ||
+      pathname === '/api/subscribe')
+  ) {
+    try {
+      const body = await parseBody(req);
+      const email = String(body.email || url.searchParams.get('email') || '').trim();
+
+      if (!email || !email.includes('@')) {
+        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
+        res.end(JSON.stringify({ ok: false, error: 'Please enter a valid email address.' }));
+        return;
+      }
+
+      subscriptions.push({ email, subscribedAt: new Date().toISOString() });
+      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
+      res.end(
+        JSON.stringify({
+          ok: true,
+          email,
+          message: `Thanks for subscribing, ${email}! You're on The Daily Grind list.`
+        })
+      );
+      return;
+    } catch {
+      res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
+      res.end(JSON.stringify({ ok: false, error: 'Unable to process your subscription right now.' }));
+      return;
+    }
+  }
+
+  if (req.method === 'GET' || req.method === 'HEAD') {
+    const requestedPath = pathname === '/' ? '/index.html' : pathname;
+    const safePath = path.normalize(requestedPath).replace(/^(\.\.(\/|\\|$))+/, '');
+    const filePath = path.join(ROOT_DIR, safePath);
+
+    if (!filePath.startsWith(ROOT_DIR)) {
+      res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
+      res.end('Forbidden');
+      return;
+    }
+
+    fs.readFile(filePath, (err, content) => {
+      if (err) {
+        if (err.code === 'ENOENT') {
+          res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
+          res.end('Not Found');
+        } else {
+          res.writeHead(500, { 'Content-Type': 'text/plain; charset=utf-8' });
+          res.end('Internal Server Error');
+        }
+        return;
+      }
+
+      const ext = path.extname(filePath).toLowerCase();
+      const contentType = MIME_TYPES[ext] || 'application/octet-stream';
+      res.writeHead(200, { 'Content-Type': contentType });
+      if (req.method === 'HEAD') {
+        res.end();
+      } else {
+        res.end(content);
+      }
+    });
+    return;
+  }
+
+  res.writeHead(405, { 'Content-Type': 'text/plain; charset=utf-8' });
+  res.end('Method Not Allowed');
+});
+
+if (require.main === module) {
+  server.listen(PORT, '0.0.0.0', () => {
+    console.log(`Daily Grind server running at http://localhost:${PORT}`);
+  });
+}
+
+module.exports = { server, CSP_HEADER };

