+import type { APIRoute } from 'astro';
+import { formatOriginBoundSms, generateSixDigitOtp, normalizeOtpDomain } from '../../utils/smsOtp';
+
+const PHONE_REGEX = /^\+?[0-9\s\-()]{7,20}$/;
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  try {
+    let phone = '';
+    let domain = '';
+
+    const contentType = request.headers.get('content-type') || '';
+    if (contentType.includes('application/json')) {
+      const body = await request.json();
+      phone = String(body.phone || '').trim();
+      domain = String(body.domain || '').trim();
+    } else {
+      const formData = await request.formData();
+      phone = String(formData.get('phone') || '').trim();
+      domain = String(formData.get('domain') || '').trim();
+    }
+
+    if (!phone || !PHONE_REGEX.test(phone)) {
+      return new Response(
+        JSON.stringify({
+          error: 'Please enter a valid phone number.',
+        }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    const hostDomain = normalizeOtpDomain(domain || url.hostname || 'localhost');
+    const otpCode = generateSixDigitOtp();
+    const smsMessage = formatOriginBoundSms(hostDomain, otpCode);
+
+    if (session) {
+      await session.set('pendingOtp', {
+        phone,
+        code: otpCode,
+        expiresAt: Date.now() + 10 * 60 * 1000,
+      });
+    }
+
+    return new Response(
+      JSON.stringify({
+        success: true,
+        phone,
+        smsMessage,
+      }),
+      {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  } catch {
+    return new Response(
+      JSON.stringify({
+        error: 'Unable to send verification code. Please try again.',
+      }),
+      {
+        status: 500,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+};
