+        var itemCard = e.target.closest('[data-item-card]');
+        if (itemCard) {
+          e.preventDefault();
+          var cardItemId = itemCard.getAttribute('data-item-card');
+          navigateToItem(cardItemId);
+          return;
+        }
+
+        // 2. Check for Back action
+        var backTrigger = e.target.closest('[data-action="back"]');
+        if (backTrigger) {
+          e.preventDefault();
+          navigateBack();
+          return;
+        }
+
+        // 3. Check for Root/Home action
+        var rootTrigger = e.target.closest('[data-action="root"], [data-nav-root]');
+        if (rootTrigger) {
+          e.preventDefault();
+          navigateToRoot();
+          return;
+        }
+
+        // 4. Check for Level-2 Origin drill-down
+        var drillOrigin = e.target.closest('[data-action="drill-origin"]');
+        if (drillOrigin) {
+          e.preventDefault();
+          pushStack(['home', state.activeItemId, 'origin']);
+          return;
+        }
+
+        // 5. Scroll to Seasonal Favorites on Home
+        var scrollSeasonal = e.target.closest('[data-scroll-seasonal]');
+        if (scrollSeasonal) {
