+        }
+      });
+
+      // Keyboard navigation support (Enter/Space on cards, Escape to pop stack)
+      document.addEventListener('keydown', function (e) {
+        if (e.key === 'Escape' && state.stack.length > 1) {
+          e.preventDefault();
+          navigateBack();
+          return;
+        }
+
+        if ((e.key === 'Enter' || e.key === ' ') && document.activeElement) {
+          var focusedCard = document.activeElement.closest('[data-item-card]');
+          if (focusedCard && document.activeElement === focusedCard) {
+            e.preventDefault();
+            navigateToItem(focusedCard.getAttribute('data-item-card'));
+          }
+        }
+      });
+
+      // Customization pills interactivity
+      document.getElementById('size-options').addEventListener('click', function (e) {
