+        if (!pill) return;
+        document.querySelectorAll('#size-options .option-pill').forEach(function (b) {
+          b.classList.remove('is-selected');
+        });
+        pill.classList.add('is-selected');
+        var offset = parseFloat(pill.getAttribute('data-price-offset') || '0');
+        state.selectedSizeOffset = offset;
+        var item = ITEMS[state.activeItemId] || ITEMS['seasonal'];
+        var updatedPrice = (item.basePrice + offset).toFixed(2);
+        document.getElementById('detail-price').textContent = '$' + updatedPrice;
+        document.getElementById('order-btn-price').textContent = '$' + updatedPrice;
+      });
+
+      document.getElementById('prep-options').addEventListener('click', function (e) {
+        var pill = e.target.closest('.option-pill');
+        if (!pill) return;
+        document.querySelectorAll('#prep-options .option-pill').forEach(function (b) {
+          b.classList.remove('is-selected');
+        });
+        pill.classList.add('is-selected');
+      });
+
+      // Add to Order button
+      document.getElementById('add-to-order-btn').addEventListener('click', function () {
+        state.cartCount += 1;
+        document.getElementById('nav-cart-count').textContent = String(state.cartCount);
+        document.getElementById('detail-cart-count').textContent = String(state.cartCount);
+        var item = ITEMS[state.activeItemId] || ITEMS['seasonal'];
+        showToast('Added ' + item.title + ' to your order bag!');
