+      });
+
+      // ==================== SWIPE-BACK GESTURE ENGINE ====================
+      // Supports Touch (touchstart/touchmove/touchend), Pointer, Mouse drag, and Trackpad horizontal swipe
+
+      var gesture = {
+        tracking: false,
+        dragging: false,
+        startX: 0,
+        startY: 0,
+        currentX: 0,
+        startTime: 0,
+        activeEl: null,
+        behindEl: null
+      };
+
+      function getCurrentScreens() {
+        var depth = state.stack.length - 1;
+        if (depth === 1) {
+          return { active: screenDetail, behind: screenHome };
+        }
+        if (depth >= 2) {
