+function parseCookies(cookieHeader = '') {
+  const cookies = {};
+  for (const part of cookieHeader.split(';')) {
+    const [rawName, ...rest] = part.trim().split('=');
+    if (!rawName) continue;
+    cookies[rawName] = decodeURIComponent(rest.join('='));
+  }
+  return cookies;
