+export async function consumeSessionNonce(sessionId) {
+  if (!sessionId) return null;
+  const record = sessionNonceStore.get(sessionId);
+  // Immediately delete so an intercepted token cannot be replayed
+  sessionNonceStore.delete(sessionId);
+  if (!record) return null;
+  if (Date.now() - record.createdAt > NONCE_TTL_MS) {
