+  rawToken,
+  sessionId,
+  expectedAudience = RP_ORIGIN,
+}) {
+  const trimmedEmail = String(submittedEmail || '').trim();
+  const trimmedToken = String(rawToken || '').trim();
+
+  // Atomically read and delete the single-use nonce from server-side session state
+  const expectedNonce = await consumeSessionNonce(sessionId);
+
+  if (!trimmedEmail || !trimmedEmail.includes('@')) {
+    const error = new Error('Please provide a valid email address.');
+    error.statusCode = 400;
+    throw error;
+  }
+
+  if (!password || String(password).length < 8) {
+    const error = new Error('Password must be at least 8 characters long.');
+    error.statusCode = 400;
+    throw error;
+  }
+
+  if (trimmedToken && expectedNonce) {
+    try {
+      await verifyEmailVerificationToken({
+        rawToken: trimmedToken,
+        submittedEmail: trimmedEmail,
+        expectedNonce,
+        expectedAudience,
+      });
+      // Fast path: email ownership is cryptographically verified; skip OTP email.
+      return completeAccountCreation({
+        submittedEmail: trimmedEmail,
+        name: String(name || '').trim(),
+        drinkPreference: String(drinkPreference || 'espresso').trim(),
+      });
+    } catch (err) {
+      // Log token verification failures before falling back to standard email verification.
+      console.error('Email verification token check failed:', err);
+    }
+  }
+
+  // Fallback path: send standard OTP code or magic link email to submittedEmail.
+  return sendTraditionalVerificationEmail({
+    submittedEmail: trimmedEmail,
+    name: String(name || '').trim(),
+    drinkPreference: String(drinkPreference || 'espresso').trim(),
+  });
+}
+
+async function readRequestBody(req) {
+  const chunks = [];
+  for await (const chunk of req) {
+    chunks.push(chunk);
+  }
+  const rawBody = Buffer.concat(chunks).toString('utf8');
+  const contentType = req.headers['content-type'] || '';
+
+  if (contentType.includes('application/json')) {
+    try {
+      return JSON.parse(rawBody || '{}');
+    } catch {
+      return {};
+    }
+  }
+
+  const params = new URLSearchParams(rawBody);
+  return Object.fromEntries(params.entries());
+}
+
+export async function requestHandler(req, res) {
+  const url = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);
+  const cookies = parseCookies(req.headers.cookie);
+
+  if (req.method === 'GET' && (url.pathname === '/' || url.pathname === '/index.html')) {
+    const { sessionId, nonce } = createSessionNonce(cookies[SESSION_COOKIE_NAME]);
+    const rawHtml = await readFile(path.join(__dirname, 'index.html'), 'utf8');
+    const renderedHtml = rawHtml.replaceAll(
+      'SERVER_GENERATED_PER_FORM_NONCE',
+      nonce
+    );
+
+    res.writeHead(200, {
+      'Content-Type': 'text/html; charset=utf-8',
+      'Cache-Control': 'no-store',
+      'Origin-Trial': ORIGIN_TRIAL_TOKEN,
+      'Set-Cookie': `${SESSION_COOKIE_NAME}=${encodeURIComponent(sessionId)}; Path=/; HttpOnly; Secure; SameSite=Lax`,
+    });
+    res.end(renderedHtml);
+    return;
+  }
+
+  if (
+    req.method === 'POST' &&
+    (url.pathname === '/api/verify-email' || url.pathname === '/api/rewards/signup')
+  ) {
+    const body = await readRequestBody(req);
+    const sessionId = cookies[SESSION_COOKIE_NAME];
+    const originHeader = req.headers.origin;
+    const expectedAudience = originHeader || RP_ORIGIN;
+
+    try {
+      const result = await handleSignupSubmission({
+        submittedEmail: body.email,
+        name: body.name,
+        password: body.password,
+        drinkPreference: body.drink_preference,
+        rawToken: body.token,
+        sessionId,
+        expectedAudience,
+      });
+
+      // Generate a fresh nonce in case the user renders or submits again
+      const { sessionId: nextSessionId, nonce: nextNonce } =
+        createSessionNonce(sessionId);
+
+      const acceptsJson = (req.headers.accept || '').includes('application/json');
+      if (acceptsJson) {
+        res.writeHead(200, {
+          'Content-Type': 'application/json; charset=utf-8',
+          'Cache-Control': 'no-store',
+          'Set-Cookie': `${SESSION_COOKIE_NAME}=${encodeURIComponent(nextSessionId)}; Path=/; HttpOnly; Secure; SameSite=Lax`,
+        });
+        res.end(JSON.stringify({ ...result, nextNonce }));
+        return;
+      }
+
+      // Standard HTML form navigation fallback response
+      res.writeHead(303, {
+        Location: `/?signup=${encodeURIComponent(result.status)}#rewards-signup`,
+        'Cache-Control': 'no-store',
+        'Set-Cookie': `${SESSION_COOKIE_NAME}=${encodeURIComponent(nextSessionId)}; Path=/; HttpOnly; Secure; SameSite=Lax`,
+      });
+      res.end();
+      return;
+    } catch (err) {
+      const statusCode = err?.statusCode || 400;
+      res.writeHead(statusCode, {
+        'Content-Type': 'application/json; charset=utf-8',
+        'Cache-Control': 'no-store',
+      });
+      res.end(
+        JSON.stringify({
+          status: 'error',
+          message: err?.message || 'Unable to process registration.',
+        })
+      );
+      return;
+    }
+  }
+
+  res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
+  res.end('Not Found');
+}
+
+if (
+  process.argv[1] &&
+  import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href
+) {
+  const server = http.createServer(requestHandler);
+  server.listen(PORT, () => {
+    console.log(`The Daily Grind server listening on http://localhost:${PORT}`);
+  });
+}

