+      'category',
+      'badge',
+      'roast',
+      'notes',
+      'calories',
+      'cta-text',
+      'favorited'
+    ];
+  }
+
+  constructor() {
+    super();
+    this.attachShadow({ mode: 'open' });
+    this._selectedSize = 'Medium';
