+/**
+ * <coffee-menu> Web Component
+ * Interactive menu section with category filtering, search, sorting, and ARIA live announcements.
+ */
+export class CoffeeMenu extends HTMLElement {
+  static get observedAttributes() {
+    return ['heading', 'subheading', 'active-filter', 'search-query'];
+  }
+
+  constructor() {
+    super();
+    this.attachShadow({ mode: 'open' });
+    this._activeFilter = 'all';
+    this._searchQuery = '';
+    this._sortOrder = 'featured';
+    this._filters = [
+      { id: 'all', label: 'All Coffees' },
+      { id: 'seasonal', label: 'Seasonal' },
+      { id: 'espresso', label: 'Espresso' },
+      { id: 'cold-brew', label: 'Cold Brew' },
+      { id: 'favorites', label: 'Favorites' }
+    ];
+    this._onFavoriteChanged = () => {
+      if (this._activeFilter === 'favorites') {
+        this._applyFilters();
+      }
+    };
+  }
+
+  connectedCallback() {
+    if (this.hasAttribute('active-filter')) {
+      this._activeFilter = this.getAttribute('active-filter') || 'all';
+    }
+    if (this.hasAttribute('search-query')) {
+      this._searchQuery = this.getAttribute('search-query') || '';
+    }
+    this.render();
+    this.addEventListener('coffee-favorite', this._onFavoriteChanged);
+  }
+
+  disconnectedCallback() {
+    this.removeEventListener('coffee-favorite', this._onFavoriteChanged);
+  }
+
+  attributeChangedCallback(name, oldValue, newValue) {
+    if (oldValue === newValue || !this.isConnected) return;
+    if (name === 'active-filter') {
+      this._activeFilter = newValue || 'all';
+      this._updateFilterTabs();
+      this._applyFilters();
+    } else if (name === 'search-query') {
+      this._searchQuery = newValue || '';
+      const input = this.shadowRoot.querySelector('.search-input');
+      if (input && input.value !== this._searchQuery) {
+        input.value = this._searchQuery;
+      }
+      this._applyFilters();
+    } else {
+      this.render();
+    }
+  }
+
+  get heading() {
+    return this.getAttribute('heading') || 'Seasonal Favorites';
+  }
+
+  get subheading() {
+    return (
+      this.getAttribute('subheading') ||
+      'Handcrafted small-batch roasts and signature café creations.'
+    );
+  }
+
+  _getSlottedCards() {
+    const slot = this.shadowRoot ? this.shadowRoot.querySelector('slot:not([name])') : null;
+    if (slot && typeof slot.assignedElements === 'function') {
+      const assigned = slot.assignedElements({ flatten: true });
+      if (assigned.length > 0) {
+        return assigned.filter((el) => el.tagName.toLowerCase() === 'coffee-card' || el.classList.contains('card'));
+      }
+    }
+    return Array.from(this.querySelectorAll('coffee-card, .card'));
+  }
+
+  _setFilter(filterId) {
+    this._activeFilter = filterId;
+    this.setAttribute('active-filter', filterId);
+    this._updateFilterTabs();
+    this._applyFilters();
+    this.dispatchEvent(
+      new CustomEvent('menu-filter-change', {
+        bubbles: true,
+        composed: true,
+        detail: {
+          filter: this._activeFilter,
+          search: this._searchQuery,
+          sort: this._sortOrder
+        }
+      })
+    );
+  }
