+      const nextFilter = ids[nextIndex];
+      this._setFilter(nextFilter);
+      const buttons = this.shadowRoot.querySelectorAll('.filter-tab');
+      if (buttons[nextIndex]) {
+        buttons[nextIndex].focus();
+      }
+    }
+  }
