+/**
+ * <dg-navbar> Web Component
+ * Accessible, responsive navigation bar with mobile menu toggle and live Order Bag drawer.
+ */
+export class DgNavbar extends HTMLElement {
+  static get observedAttributes() {
+    return ['brand', 'cart-count'];
+  }
+
+  constructor() {
+    super();
+    this.attachShadow({ mode: 'open' });
+    this._mobileMenuOpen = false;
+    this._cartDrawerOpen = false;
+    this._items = [];
+    this._boundOrderHandler = (e) => this._handleOrderEvent(e);
+    this._boundKeydownHandler = (e) => this._handleGlobalKeydown(e);
+  }
+
+  connectedCallback() {
+    this.render();
+    document.addEventListener('coffee-order', this._boundOrderHandler);
+    document.addEventListener('keydown', this._boundKeydownHandler);
+  }
+
+  disconnectedCallback() {
+    document.removeEventListener('coffee-order', this._boundOrderHandler);
+    document.removeEventListener('keydown', this._boundKeydownHandler);
+  }
+
+  attributeChangedCallback(name, oldValue, newValue) {
+    if (oldValue !== newValue && this.isConnected) {
+      this._updateCartDisplay();
+    }
+  }
+
+  get brand() {
+    return this.getAttribute('brand') || 'THE DAILY GRIND';
+  }
+
+  get totalCount() {
+    return this._items.reduce((sum, item) => sum + item.quantity, 0);
+  }
+
+  get totalPrice() {
+    return this._items.reduce((sum, item) => sum + item.numericPrice * item.quantity, 0);
+  }
+
+  _handleOrderEvent(event) {
+    const detail = event.detail || {};
+    const title = detail.title || 'Artisanal Coffee';
+    const size = detail.size || 'Medium';
+    const milk = detail.milk || 'Standard';
+    const numericPrice = Number(detail.numericPrice) || 4.5;
+    const key = `${title}__${size}__${milk}`;
+
+    const existing = this._items.find((i) => i.key === key);
+    if (existing) {
+      existing.quantity += 1;
+    } else {
+      this._items.push({
+        key,
+        title,
+        size,
+        milk,
+        numericPrice,
+        quantity: 1
+      });
+    }
+
+    this.setAttribute('cart-count', String(this.totalCount));
+    this._updateCartDisplay();
+  }
+
+  _handleGlobalKeydown(event) {
+    if (event.key === 'Escape') {
+      if (this._cartDrawerOpen) {
+        this._cartDrawerOpen = false;
+        this._updateCartDisplay();
+        const cartBtn = this.shadowRoot.querySelector('.cart-toggle-btn');
+        if (cartBtn) cartBtn.focus();
+      } else if (this._mobileMenuOpen) {
+        this._mobileMenuOpen = false;
+        this._updateMobileMenu();
+        const menuBtn = this.shadowRoot.querySelector('.mobile-toggle');
+        if (menuBtn) menuBtn.focus();
+      }
+    }
+  }
+
+  _adjustItemQuantity(key, delta) {
+    const idx = this._items.findIndex((i) => i.key === key);
+    if (idx === -1) return;
+    this._items[idx].quantity += delta;
+    if (this._items[idx].quantity <= 0) {
+      this._items.splice(idx, 1);
+    }
+    this.setAttribute('cart-count', String(this.totalCount));
+    this._updateCartDisplay();
+  }
+
+  _updateMobileMenu() {
+    if (!this.shadowRoot) return;
+    const menuBtn = this.shadowRoot.querySelector('.mobile-toggle');
+    const navList = this.shadowRoot.querySelector('.nav-links');
+    if (menuBtn && navList) {
+      menuBtn.setAttribute('aria-expanded', String(this._mobileMenuOpen));
+      navList.classList.toggle('open', this._mobileMenuOpen);
+    }
+  }
+
+  _updateCartDisplay() {
+    if (!this.shadowRoot) return;
+    const countBadge = this.shadowRoot.querySelector('.cart-badge');
+    const cartBtn = this.shadowRoot.querySelector('.cart-toggle-btn');
+    const drawer = this.shadowRoot.querySelector('#order-bag-drawer');
+    const listContainer = this.shadowRoot.querySelector('.bag-items');
+    const totalEl = this.shadowRoot.querySelector('.bag-total-amount');
+
+    const count = this.totalCount;
+    if (countBadge) {
+      countBadge.textContent = String(count);
+    }
+    if (cartBtn) {
+      cartBtn.setAttribute('aria-expanded', String(this._cartDrawerOpen));
+      cartBtn.setAttribute('aria-label', `Order bag, ${count} ${count === 1 ? 'item' : 'items'}`);
+    }
+    if (drawer) {
+      drawer.hidden = !this._cartDrawerOpen;
+    }
+    if (totalEl) {
+      totalEl.textContent = `$${this.totalPrice.toFixed(2)}`;
+    }
+    if (listContainer) {
+      if (this._items.length === 0) {
+        listContainer.innerHTML = `<p class="empty-bag">Your order bag is empty. Add a seasonal favorite below!</p>`;
+      } else {
+        listContainer.innerHTML = this._items
+          .map(
+            (item) => `
+            <div class="bag-item">
+              <div class="bag-item-info">
+                <strong>${item.title}</strong>
+                <span>${item.size}${item.milk && item.milk !== 'Standard' ? ` • ${item.milk}` : ''} — $${(
+              item.numericPrice * item.quantity
+            ).toFixed(2)}</span>
+              </div>
+              <div class="bag-item-controls" role="group" aria-label="Quantity controls for ${item.title}">
+                <button type="button" class="qty-btn" data-key="${item.key}" data-delta="-1" aria-label="Decrease quantity of ${item.title}">−</button>
+                <span class="qty-val" aria-live="polite">${item.quantity}</span>
+                <button type="button" class="qty-btn" data-key="${item.key}" data-delta="1" aria-label="Increase quantity of ${item.title}">+</button>
+              </div>
+            </div>
+          `
+          )
+          .join('');
+
+        listContainer.querySelectorAll('.qty-btn').forEach((btn) => {
+          btn.addEventListener('click', () => {
+            this._adjustItemQuantity(btn.dataset.key, Number(btn.dataset.delta));
+          });
+        });
+      }
+    }
+  }
