+        orders.push(orderRecord);
+
+        // Sync form inputs and visual card state
+        const drinkSelect = document.getElementById('order-drink');
+        const sizeSelect = document.getElementById('order-size');
+        const milkSelect = document.getElementById('order-milk');
+        const qtyInput = document.getElementById('order-quantity');
+        const custInput = document.getElementById('order-customer');
+
+        if (drinkSelect) drinkSelect.value = matched.name;
+        if (sizeSelect && ['Small', 'Medium', 'Large'].includes(size)) sizeSelect.value = size;
+        if (milkSelect && ['Oat', 'Whole', 'Almond', 'None'].includes(milk)) milkSelect.value = milk;
+        if (qtyInput) qtyInput.value = String(quantity);
+        if (custInput && customerName) custInput.value = customerName;
+
+        highlightDrinkCard(matched.id);
+        showDrinkDetails(matched.id);
+
+        const message =
+          'Order ' + orderRecord.orderId + ' confirmed: ' +
+          quantity + 'x ' + size + ' ' + matched.name +
+          (milk && milk !== 'None' ? ' with ' + milk + ' milk' : '') +
+          ' ($' + totalPrice.toFixed(2) + ').';
+
+        renderOrdersUI(orderRecord, message);
+
+        return {
+          success: true,
+          message: message,
+          order: orderRecord,
+          cartTotalItems: orders.reduce((s, o) => s + o.quantity, 0),
+          cartTotalPrice: Number(orders.reduce((s, o) => s + o.totalPrice, 0).toFixed(2))
+        };
+      }
+
+      function updatePageUI(params = {}) {
+        const action = params.action || 'highlight';
+        const drink = params.drink || params.drinkName || params.target || '';
+        const filterQuery = params.filter || params.query || '';
+        const bannerMessage = params.message || params.statusMessage || '';
+
+        let matched = null;
+        if (drink) {
+          matched = showDrinkDetails(drink).drink;
+        }
+
+        if (filterQuery !== undefined && params.action === 'filter') {
+          const q = String(filterQuery).toLowerCase().trim();
+          const cards = document.querySelectorAll('#menu-grid .card');
+          cards.forEach((card) => {
+            const id = card.getAttribute('data-drink-id') || '';
+            const item = findDrink(id);
+            const isMatch =
+              !q ||
+              (item &&
+                (item.name.toLowerCase().includes(q) ||
+                  item.description.toLowerCase().includes(q) ||
+                  item.tags.some((t) => t.toLowerCase().includes(q))));
+            card.style.display = isMatch ? '' : 'none';
+          });
+        } else if (action === 'reset') {
+          const cards = document.querySelectorAll('#menu-grid .card');
+          cards.forEach((card) => {
+            card.style.display = '';
+            card.classList.remove('highlighted');
+          });
+          const panel = document.getElementById('drink-details-panel');
+          if (panel) panel.classList.remove('active');
+        }
+
+        if (bannerMessage) {
+          const bannerEl = document.getElementById('order-status-banner');
+          if (bannerEl) {
+            bannerEl.textContent = bannerMessage;
+            bannerEl.classList.add('active');
+          }
+        }
+
+        return {
+          success: true,
+          action: action,
+          highlightedDrink: matched ? matched.name : null,
+          message: bannerMessage || (matched ? 'Updated UI for ' + matched.name : 'UI updated successfully')
+        };
+      }
+
+      // Bind form submit event
+      const orderForm = document.getElementById('drink-order-form');
+      if (orderForm) {
+        orderForm.addEventListener('submit', function (e) {
+          e.preventDefault();
+          const formData = new FormData(orderForm);
+          orderDrink({
+            drink: formData.get('drink'),
+            size: formData.get('size'),
+            milk: formData.get('milk'),
+            quantity: Number(formData.get('quantity') || 1),
+            customerName: formData.get('customerName') || ''
+          });
+        });
+      }
+
+      // Format response payload compatible with WebMCP / MCP tool responses as well as direct inspection
+      function formatToolResponse(data) {
+        return {
+          ...data,
+          content: [
+            {
+              type: 'text',
+              text: JSON.stringify(data)
+            }
+          ]
+        };
+      }
+
+      const clientTools = [
+        {
+          name: 'get_seasonal_favorites_menu',
+          description: 'Query the "Seasonal Favorites" coffee menu on The Daily Grind homepage, including drink names, descriptions, prices, sizes, milk options, and dietary tags.',
+          inputSchema: {
+            type: 'object',
+            properties: {
+              query: {
+                type: 'string',
+                description: 'Optional search keyword or drink name (e.g., "Maple Oat Latte", "espresso", "cold brew", "oat").'
+              },
+              category: {
+                type: 'string',
+                description: 'Optional category filter (e.g., "seasonal", "espresso", "cold-brew").'
+              },
+              maxPrice: {
+                type: 'number',
+                description: 'Optional maximum price filter in USD.'
+              }
+            }
+          },
+          execute: async (params = {}) => formatToolResponse(querySeasonalMenu(params))
+        },
+        {
+          name: 'order_drink',
+          description: 'Trigger an interactive drink order from the Seasonal Favorites coffee menu and update the order cart and status UI on the page.',
+          inputSchema: {
+            type: 'object',
+            properties: {
+              drink: {
+                type: 'string',
+                description: 'Name or ID of the drink to order (e.g., "Maple Oat Latte", "Dark Roast Espresso", "Cold Brew").'
+              },
+              size: {
+                type: 'string',
+                enum: ['Small', 'Medium', 'Large'],
+                description: 'Drink size (Small, Medium, or Large).'
+              },
+              milk: {
+                type: 'string',
+                description: 'Milk preference (e.g., "Oat", "Whole", "Almond", "None").'
+              },
+              quantity: {
+                type: 'number',
+                description: 'Number of drinks to order (default: 1).'
+              },
+              customerName: {
+                type: 'string',
+                description: 'Optional customer name or order notes.'
+              }
+            },
+            required: ['drink']
+          },
+          execute: async (params = {}) => formatToolResponse(orderDrink(params))
+        },
+        {
+          name: 'update_menu_ui',
+          description: 'Trigger interactive UI updates on the Daily Grind homepage such as highlighting a Seasonal Favorites drink card, viewing drink details, filtering visible menu cards, or displaying a status banner.',
+          inputSchema: {
+            type: 'object',
+            properties: {
+              action: {
+                type: 'string',
+                enum: ['highlight', 'details', 'filter', 'reset'],
+                description: 'The UI update action to perform.'
+              },
+              drink: {
+                type: 'string',
+                description: 'Drink name or ID to highlight or display details for (e.g., "Maple Oat Latte").'
+              },
+              filter: {
+                type: 'string',
+                description: 'Filter keyword when action is "filter".'
+              },
+              message: {
+                type: 'string',
+                description: 'Optional status banner message to display on the page.'
+              }
+            }
+          },
+          execute: async (params = {}) => formatToolResponse(updatePageUI(params))
+        }
+      ];
+
+      // Expose WebMCP (navigator.modelContext) and register tools for browser AI agents
+      if (typeof navigator !== 'undefined') {
+        const registeredToolsMap = new Map();
+
+        if (!navigator.modelContext) {
+          navigator.modelContext = {
+            registerTool(tool) {
+              if (tool && tool.name) {
+                registeredToolsMap.set(tool.name, tool);
+              }
+            },
+            unregisterTool(name) {
+              registeredToolsMap.delete(name);
+            },
+            provideContext(context) {
+              registeredToolsMap.clear();
+              if (context && Array.isArray(context.tools)) {
+                context.tools.forEach((t) => {
+                  if (t && t.name) registeredToolsMap.set(t.name, t);
+                });
+              }
+            },
+            clearContext() {
+              registeredToolsMap.clear();
+            },
+            getTools() {
+              return Array.from(registeredToolsMap.values());
+            }
+          };
+        }
+
+        if (typeof navigator.modelContext.provideContext === 'function') {
+          try {
+            navigator.modelContext.provideContext({ tools: clientTools });
+          } catch (_) {
+            // Fallback to individual registerTool calls if provideContext signature differs
+          }
+        }
+
+        if (typeof navigator.modelContext.registerTool === 'function') {
+          clientTools.forEach((tool) => {
+            try {
+              navigator.modelContext.registerTool(tool);
+            } catch (_) {
+              // Ignore duplicate registration errors if provideContext already registered it
+            }
+          });
+        }
+      }
+
+      // Also expose convenient global helpers for direct agent discovery / invocation
+      window.dailyGrindApp = {
+        menu: SEASONAL_FAVORITES_MENU,
+        orders: orders,
+        tools: clientTools,
+        querySeasonalMenu: querySeasonalMenu,
+        orderDrink: orderDrink,
+        showDrinkDetails: showDrinkDetails,
+        highlightDrinkCard: highlightDrinkCard,
+        updatePageUI: updatePageUI
+      };
+    })();
+  </script>
 </body>

