+export interface ArticleSummary {
+  slug: string;
+  title: string;
+  summary: string;
+  image?: string;
+  category?: string;
+  author?: string;
+  date?: string;
+  readingTime?: number;
+}
+
+export const ARTICLE_SORT_ORDERS = ['newest', 'oldest', 'title_asc'] as const;
+export type ArticleSortOrder = (typeof ARTICLE_SORT_ORDERS)[number];
+
+/**
+ * Starting in Chrome 156, `toolactivated` and `toolcancel` events are dispatched
+ * on `document.modelContext`. Older versions dispatch them on `window`.
+ * Feature-detect the event handler property to pick the right target.
+ */
+export function listenModelContextEvent(
+  type: 'toolactivated' | 'toolcancel',
+  listener: (event: ToolActivatedEvent | ToolCancelEvent) => void,
+  options?: boolean | AddEventListenerOptions
+): () => void {
+  if (typeof document === 'undefined' || typeof window === 'undefined') {
+    return () => {};
+  }
+  const target: EventTarget =
+    `on${type}` in (document.modelContext ?? {}) ? document.modelContext! : window;
+  const wrapped = listener as EventListener;
+  target.addEventListener(type, wrapped, options);
+  return () => {
+    target.removeEventListener(type, wrapped, options);
+  };
+}
